using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// The player's stamina: spent by sprinting, crouching, jumping, dashing, rolling, weapons and traits, regenerated by
/// <c>incrementValue</c> every <c>tickRate</c> seconds while nothing is spending it over time.
/// </summary>
/// <remarks>
/// Regeneration is a timer advanced by <see cref="TickRegen"/> (not a coroutine), so the player's movement simulation
/// can step it - and a network replay can step it again - exactly like the server does. While a
/// <see cref="MovementStateMachine"/> drives it (<see cref="DrivenBySimulation"/>) the movement step ticks it;
/// otherwise Update does, with the frame time. <see cref="GetRegenState"/>/<see cref="SetRegenState"/> save and
/// restore the timer for the movement snapshot.
/// </remarks>
public class StaminaManager : StatusManager
{
    [Header("Stamina-related fields")]
    private Coroutine staminaRegenerationRoutine;
    private int activeConsumptionRoutines = 0;
    private List<CoroutineInfo> staminaEffectRoutines = new List<CoroutineInfo>();
    public Coroutine StaminaRegenerationRoutine { get => staminaRegenerationRoutine; set => staminaRegenerationRoutine = value; }
    public List<CoroutineInfo> StaminaEffectRoutines { get => staminaEffectRoutines; set => staminaEffectRoutines = value; }
    private void Start()
    {
        currentValue = maxValue;
    }
    // Seconds until the next regeneration amount (valid while isRegenerating).
    private float regenTimer;

    /// <summary>
    /// Set by the player's <see cref="MovementStateMachine"/> while its simulation step calls <see cref="TickRegen"/>;
    /// Update then leaves regeneration alone (it would regenerate twice, outside the simulated tick).
    /// </summary>
    [System.NonSerialized] public bool DrivenBySimulation;

    /// <summary>True while regeneration is running (between its first and last amount).</summary>
    public bool IsRegenerating => isRegenerating;

    private void Update()
    {
        if (!DrivenBySimulation)
            TickRegen(Time.deltaTime);
    }

    /// <summary>
    /// Advances regeneration by <paramref name="dt"/> seconds. It starts when stamina is below max and nothing spends
    /// it over time, adds the first amount at once and then one every <c>tickRate</c> seconds, and stops at max or as
    /// soon as something starts spending stamina over time - the same rhythm as the old regeneration coroutine.
    /// Does nothing on a replica (the server's value arrives through replication).
    /// </summary>
    public void TickRegen(float dt)
    {
        if (IsReplica)
            return;
        if (!isRegenerating)
        {
            if (isConsuming || currentValue >= maxValue)
                return;
            isRegenerating = true;
            if (RegenAmount())
                regenTimer = tickRate;
            return;
        }
        regenTimer -= dt;
        if (regenTimer > 0f)
            return;
        if (currentValue >= maxValue)
        {
            isRegenerating = false;
            return;
        }
        if (RegenAmount())
            regenTimer = tickRate;
    }

    // Adds one regeneration amount; false (and regeneration stops) when something is spending stamina over time.
    private bool RegenAmount()
    {
        currentValue += incrementValue;
        UpdateStaminaBar();
        if (!isConsuming)
            return true;
        isRegenerating = false;
        return false;
    }

    /// <summary>The regeneration timer, for a movement snapshot: running or not, and seconds until its next amount.</summary>
    public void GetRegenState(out bool regenerating, out float secondsToNext)
    {
        regenerating = isRegenerating;
        secondsToNext = isRegenerating ? regenTimer : 0f;
    }

    /// <summary>Restores the regeneration timer saved by <see cref="GetRegenState"/> (movement reconciliation).</summary>
    public void SetRegenState(bool regenerating, float secondsToNext)
    {
        isRegenerating = regenerating;
        regenTimer = regenerating && !float.IsNaN(secondsToNext) && !float.IsInfinity(secondsToNext) ? secondsToNext : 0f;
    }

    protected override void OnReplicaChanged(bool on)
    {
        // The base stopped every routine and cleared the flags; the timer restarts from scratch when regeneration does.
        staminaRegenerationRoutine = null;
        regenTimer = 0f;
    }
    public void UpdateStaminaBar()
    {
        UpdateBar(currentValue, maxValue, uiImage);
        currentValue = Mathf.Clamp(currentValue, 0, maxValue);
    }
    public void ConsumeStamina(float amount)
    {
        if (IsReplica) return; // the server's value arrives through replication
        if (currentValue <= 0) return;
        currentValue -= RemoveFactor(amount);
    }
    public override bool HasEnougCurrentValue(float amount) => currentValue - amount >= 1;

    protected override void UpdateStatus() => UpdateBar();
    protected override float AddFactor(float amount) => ApplyFactor(amount, incrementFactor);
    protected override float RemoveFactor(float amount) => ApplyFactor(amount, decrementFactor);

    // Method to signal the regeneration coroutine to stop
    public void StopStaminaRegeneration() => isConsuming = true;


    public void AddStaminaEffect(string effectName, float staminaAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
        => AddEffect(StaminaEffectRoutines, effectName, staminaAmount, timeBuffEffect, tickCooldown, isProcedural, isStackable, ApplyStaminaEffectRoutine);
    public void AddStaminaHealFactorEffect(string effectName, float staminaHealFactorAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
        => AddEffect(StaminaEffectRoutines, effectName, staminaHealFactorAmount, timeBuffEffect, tickCooldown, isProcedural, isStackable, ApplyStaminaHealFactorEffectRoutine);
    public void AddStaminaDamageFactorEffect(string effectName, float staminaDamageFactorAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
        => AddEffect(StaminaEffectRoutines, effectName, staminaDamageFactorAmount, timeBuffEffect, tickCooldown, isProcedural, isStackable, ApplyStaminaDamageFactorEffectRoutine);
    public void AddStaminaRegenEffect(string effectName, float staminaRegenAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
        => AddEffect(StaminaEffectRoutines, effectName, staminaRegenAmount, timeBuffEffect, tickCooldown, isProcedural, isStackable, ApplyStaminaRegenEffectRoutine);
    public void RemoveStaminaEffect(string effectName = null, Coroutine effectRoutine = null)
    {
        RemoveEffect(StaminaEffectRoutines, effectName, effectRoutine);
    }

    public void StopAllStaminaEffects()
    {
        StopAllEffects(StaminaEffectRoutines);
    }

    public void StopAllStaminaEffectsByType(bool isBuff = true)
    {
        StopAllEffectsByType(StaminaEffectRoutines, isBuff);
    }

    /// <summary>
    /// The old coroutine form of regeneration. Update no longer starts it (see <see cref="TickRegen"/>); kept for
    /// scripts that start it themselves.
    /// </summary>
    public IEnumerator RegenerateStaminaRoutine()
    {
        if (isConsuming)
        {
            isRegenerating = false;
            yield break;
        }

        isRegenerating = true;

        while (currentValue < maxValue)
        {
            currentValue += incrementValue;
            UpdateStaminaBar();

            if (isConsuming)
            {
                isRegenerating = false;
                yield break;
            }

            yield return new WaitForSeconds(tickRate);
        }

        isRegenerating = false;
    }

    /// <summary>
    /// Spends <paramref name="amount"/> now and again every <paramref name="staminaTickConsumption"/> seconds until
    /// stopped or empty. The movement states no longer use it (their drain is part of the simulation step, see
    /// MovementState); kept for other scripts.
    /// </summary>
    public IEnumerator ConsumeStaminaRoutine(float amount = 0, float staminaTickConsumption = 0.5f)
    {
        activeConsumptionRoutines++;
        isConsuming = true;

        try
        {
            while (true)
            {
                ConsumeStamina(amount);
                UpdateStaminaBar();

                if (currentValue <= 0)
                    break;

                yield return new WaitForSeconds(staminaTickConsumption);
            }
        }
        finally
        {
            activeConsumptionRoutines--;
            isConsuming = activeConsumptionRoutines > 0; // Update flag based on remaining routines
        }
    }
    public IEnumerator ApplyStaminaEffectRoutine(string effectName, float staminaAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
    {
        return ApplyEffectRoutine(
            effectName,
            staminaAmount,
            timeBuffEffect,
            tickCooldown,
            isProcedural,
            isStackable,
            perTick =>
            {
                float newAmount = perTick > 0 ? AddFactor(perTick) : RemoveFactor(perTick);
                currentValue += newAmount;
            },
            total =>
            {
                float newAmount = total > 0 ? AddFactor(total) : RemoveFactor(total);
                currentValue += newAmount;
            },
            _ => currentValue = Mathf.Min(currentValue, maxValue)
        );
    }
    public IEnumerator ApplyStaminaHealFactorEffectRoutine(string effectName, float staminaHealFactorAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
    {
        return ApplyEffectRoutine(
            effectName,
            staminaHealFactorAmount,
            timeBuffEffect,
            tickCooldown,
            isProcedural,
            isStackable,
            perTick => incrementFactor += perTick,
            total => incrementFactor = total,
            original => incrementFactor -= original
        );
    }
    public IEnumerator ApplyStaminaDamageFactorEffectRoutine(string effectName, float staminaDamageFactorAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
    {
        return ApplyEffectRoutine(
            effectName,
            staminaDamageFactorAmount,
            timeBuffEffect,
            tickCooldown,
            isProcedural,
            isStackable,
            // Note: Original code uses incrementFactor in procedural case and decrementFactor in total case
            perTick => incrementFactor += perTick,
            total => decrementFactor = total,
            original => decrementFactor -= original
        );
    }
    public IEnumerator ApplyStaminaRegenEffectRoutine(string effectName, float staminaRegenAmount, float timeBuffEffect, float tickCooldown, bool isProcedural = false, bool isStackable = false)
    {
        return ApplyEffectRoutine(
            effectName,
            staminaRegenAmount,
            timeBuffEffect,
            tickCooldown,
            isProcedural,
            isStackable,
            perTick => incrementValue += perTick,
            total => incrementValue = total,
            original => incrementValue -= original
        );
    }
}